"use strict";

const { PrismaClient } = require("@prisma/client");
const service = require("../services");
const Queue = require("bull");
const db = new PrismaClient();

const scheduledRecipientQueue = new Queue("scheduled-recipient-send", {
    redis: { host: "127.0.0.1", port: 6379 },
});
console.log("Queue 'scheduled-recipient-send' inicializada.");

const processScheduledRecipients = async () => {
    const now = new Date();

    const pendingPackages = await db.document_packages_signers.findMany({
        where: {
            recipient_scheduled_send_at: { lte: now },
            recipients_sent_at: null,
            document_packages_header: { recipients_later: 1 },
        },
        select: {
            id: true,
            recipient_scheduled_send_at: true,
            updated_at: true,
            recipients: { select: { email: true } },
            document_packages_header: { select: { name: true } },
            company: { select: { email: true } },
            signers: { select: { status: true } },
        },
    });

    if (pendingPackages.length === 0) {
        return;
    }

    for (const pkg of pendingPackages) {
        try {
            const allSigned = pkg.signers.length > 0 && pkg.signers.every(s => s.status === "accepted");

            if (!allSigned) {
                continue;
            }

            const groupEmails = pkg.recipients.map(r => r.email).filter(Boolean);

            if (groupEmails.length === 0) {
                await db.document_packages_signers.update({
                    where: { id: pkg.id },
                    data: { recipients_sent_at: new Date() },
                });
                continue;
            }

            await service.sendGroupEmails(
                groupEmails,
                pkg.id,
                pkg.updated_at,
                pkg.document_packages_header?.name || "",
                pkg.company?.email || "",
                false,
                null,
                null
            );

            await db.document_packages_signers.update({
                where: { id: pkg.id },
                data: { recipients_sent_at: new Date() },
            });

        } catch (error) {
            console.error(`Error al enviar documentos a remitentes para ID ${pkg.id}:`, error);
        }
    }
};

scheduledRecipientQueue.process(async () => {
    await processScheduledRecipients();
});

scheduledRecipientQueue.add({}, { repeat: { cron: "*/5 * * * *" } });

module.exports = scheduledRecipientQueue;

