"use strict";

const { PrismaClient } = require("@prisma/client");
const moment = require("moment");
require("moment/locale/es");
const service = require("../services");
const genApiKey = require("generate-api-key");
const Queue = require("bull");
const db = new PrismaClient();

const scheduledSignerQueue = new Queue("scheduled-signer-send", {
    redis: { host: "127.0.0.1", port: 6379 },
});
console.log("Queue 'scheduled-signer-send' inicializada.");

const processScheduledSigners = async () => {
    const now = new Date();

    const scheduledSigners = await db.document_signers.findMany({
        where: {
            status: "scheduled",
            scheduled_send_at: {
                lte: now,
            },
        },
        select: {
            id: true,
            token: true,
            order: true,
            status: true,
            scheduled_send_at: true,
            document_package_signer_id: true,
            users: {
                select: {
                    id: true,
                    email: true,
                    firstname: true,
                    lastname: true,
                },
            },
            document_packages_signers: {
                include: {
                    company: {
                        select: {
                            id: true,
                            avatar: true,
                            fiscal_name: true,
                            email: true,
                            company_parent_id: true,
                            advanced_settings: {
                                select: {
                                    email_message: true,
                                },
                            },
                        },
                    },
                    document_packages_header: {
                        select: {
                            name: true,
                        },
                    },
                },
            },
            users: {
                select: {
                    id: true,
                    email: true,
                    firstname: true,
                    lastname: true,
                },
            },
        },
    });

    if (scheduledSigners.length === 0) {
        return;
    }

    for (const signer of scheduledSigners) {
        try {
            const previousOrder = signer.order - 1;

            if (previousOrder >= 1) {
                const previousSigner = await db.document_signers.findFirst({
                    where: {
                        document_package_signer_id: signer.document_package_signer_id,
                        order: previousOrder,
                        status: "accepted",
                    },
                });

                if (!previousSigner) {

                    continue;
                }
            }

            const user = signer.users;
            const dps = signer.document_packages_signers;
            const company = dps.company;
            const packageName = dps.document_packages_header?.name || "";

            const url = `${process.env.ENV_URL}${signer.token}`;

            await service.sendSolicitudFirma(
                user.email,
                company.avatar,
                `${user.firstname} ${user.lastname}`,
                company.fiscal_name,
                company.fiscal_name,
                genApiKey.generateApiKey({ method: "base32", dashes: false }),
                dps.expires_in_days
                    ? dps.expires_in_days.toLocaleDateString("es-ES")
                    : "",
                dps.expires_in_days
                    ? dps.expires_in_days.toLocaleTimeString()
                    : "",
                url,
                company.email,
                packageName,
                company.advanced_settings[0]?.email_message || "",
                user.id,
                dps.id,
                company.id
            );

            await db.document_signers.update({
                where: { id: signer.id },
                data: {
                    status: "send",
                    sent_sign_request_at: new Date(),
                    updated_at: new Date(),
                },
            });

        } catch (error) {
            console.error(
                `Error al enviar solicitud al firmante document_signer ID: ${signer.id}:`,
                error
            );
        }
    }
};

scheduledSignerQueue.process(async () => {
    console.log("Ejecutando job de envío programado de firmantes...");
    await processScheduledSigners();
});

scheduledSignerQueue.add({}, { repeat: { cron: "*/5 * * * *" } });

module.exports = scheduledSignerQueue;

